const __pageData = JSON.parse('{"title":"Week 04 — Deterministic data and a reference processor: generating, parsing, and summing","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"materials/week-04/PLAN.md","filePath":"materials/week-04/PLAN.md"}');
